    'mkt.footer.privacy': 'Privacy Policy',
    'mkt.footer.dataDeletion': 'Data Deletion',
    'mkt.privacy.title': 'Privacy Policy',
    'mkt.privacy.updatedPrefix': 'Aakhri update:',
    'mkt.privacy.intro': 'Yeh Privacy Policy batati hai ke eNeezam aapka data kya aur kyun jama karta hai, kahan rakhta hai, aur aap kya control kar sakte hain. Hum aapka data kabhi bechte nahi.',
    'mkt.privacy.s1Title': '1. Hum kaun hain',
    'mkt.privacy.s1Body': 'eNeezam ek order-management, courier-booking aur online-store platform hai jo Pakistani sellers ke liye hai. Is policy ke baare mein sawal ke liye {email} par rabta karein.',
    'mkt.privacy.s2Title': '2. Hum kya data jama karte hain',
    'mkt.privacy.s2Body': 'Account data: naam, email, phone, brand ka naam. Store data: store ka naam, domain, settings, products, theme. Order data: aapke customers ke order, jis mein customer ka naam, phone aur delivery address shamil hai (yeh data hum aapki taraf se sirf order aur delivery chalane ke liye sambhalte hain). Technical data: login, errors aur performance ke basic logs.',
    'mkt.privacy.s3Title': '3. Meta (Facebook) data',
    'mkt.privacy.s3Body': 'Jab aap Meta Connect istemal karte hain to hum yeh data lete hain: aapke ad account ki ID aur naam, ad performance data (kharch, impressions, clicks, reach), campaigns jo aap eNeezam se banate ya pause karte hain, aapka Meta Pixel ID, aapka Meta user ID, aur ek access token. Hum sirf do permissions mangte hain: ads_read aur ads_management. Is data ko hum sirf aapko ads ka hisaab dikhane, aapke kehne par campaigns chalane, aur aapke apne store par pixel se measurement ke liye istemal karte hain. Hum isay kisi aur ke ads ke liye, ya kisi ko bechne ke liye kabhi istemal nahi karte. Store ka Data sharing level merchant khud chunta hai: Standard mein Meta ko koi personal data nahi jata; Enhanced mein customer ka hashed (SHA-256) email, phone, naam, shehar, soobah aur mulk jata hai; Maximum mein yehi data hamare server se bhi (Conversions API) jata hai, aur hum customer ka IP address aur browser ki maloomat Meta ko pass karte hain magar apne paas store ya log nahi karte. Street address kabhi nahi bheja jata.',
    'mkt.privacy.s4Title': '4. Hum data kaise istemal karte hain',
    'mkt.privacy.s4Body': 'Service chalane ke liye (orders, courier booking, store, reports), aapko dikhane ke liye, security aur fraud se bachane ke liye, aur masail theek karne ke liye. Customer data hum marketing ke liye kisi teesre fareeq ko nahi dete.',
    'mkt.privacy.s5Title': '5. Data kahan aur kaise mehfooz hai',
    'mkt.privacy.s5Body': 'Data Supabase (database) aur Cloudflare (hosting aur network) par rakha jata hai. Meta ka access token sirf hamare server par database mein rehta hai; woh aapke browser, URL, logs ya device mein kabhi nahi bheja jata. Data transit mein encrypted hota hai aur database par access-control (row-level security) lagi hai taake har store sirf apna data dekhe.',
    'mkt.privacy.s6Title': '6. Kitni der rakhte hain',
    'mkt.privacy.s6Body': 'Account aur store ka data us waqt tak jab tak aapka account chalu hai. Meta data (token, ad account, pixel) us waqt tak jab tak aap Disconnect nahi karte, account delete nahi karte, ya Meta se eNeezam ko remove nahi karte; uske baad woh hamare active database se hata diya jata hai. Qanooni ya hisaab ki zarooratein ho to sirf utna data rakha jata hai jitna zaroori ho.',
    'mkt.privacy.s7Title': '7. Hamare service providers',
    'mkt.privacy.s7Body': 'Supabase (database aur login), Cloudflare (hosting, network, storefront). Zarurat ke mutabiq: email bhejne wali service, courier partners (aapke bookings ke liye), delivery address match karne ki AI service, aur Meta (aapke connect karne par). Yeh sab sirf service dene ke liye data istemal karte hain.',
    'mkt.privacy.s8Title': '8. Aapke haqooq',
    'mkt.privacy.s8Body': 'Aap apna data dekhne, theek karwane ya delete karwane ka haq rakhte hain. Meta data aap khud Meta Connect mein Disconnect dabake foran hata sakte hain. Poora account ya data delete karwane ke liye Data Deletion page dekhein ya {email} par likhein.',
    'mkt.privacy.s9Title': '9. Tabdeeliyan aur rabta',
    'mkt.privacy.s9Body': 'Hum yeh policy badal sakte hain; bari tabdeeli par platform ke zariye ya email se batayenge. Sawal ke liye: {email}.',
    'mkt.terms.generalTitle': 'Part A: Platform ke general Terms of Service',
    'mkt.terms.courierTitle': 'Part B: Courier-booking service ki shartein',
    'mkt.terms.generalIntro': 'eNeezam istemal karke ya account bana kar aap in Terms se ittefaq karte hain. Agar aap kisi business ki taraf se istemal kar rahe hain to aap ke paas us business ko bind karne ka ikhtiyar hona chahiye.',
    'mkt.terms.g1Title': 'A1. Service',
    'mkt.terms.g1Body': 'eNeezam orders, courier booking, products, online store aur ads ke tools deta hai. Hum features badal ya band kar sakte hain; bari tabdeeli par pehle batane ki koshish karte hain.',
    'mkt.terms.g2Title': 'A2. Account aur zimmedari',
    'mkt.terms.g2Body': 'Aap apne login, team members aur unke kaam ke zimmedar hain. Aapka diya hua data sahi aur qanooni hona chahiye, aur aapke paas apne customers ka data istemal karne ka haq hona chahiye.',
    'mkt.terms.g3Title': 'A3. Munasib istemal',
    'mkt.terms.g3Body': 'Service ko dhoka dene, ghair-qanooni cheezein bechne, doosron ka data churane, ya system ko nuqsan pohanchane ke liye istemal nahi kiya ja sakta.',
    'mkt.terms.g4Title': 'A4. Teesre fareeq ki services',
    'mkt.terms.g4Body': 'Shopify, courier companies aur Meta jaisi services un ki apni shartein rakhti hain. Meta Connect istemal karne par aap Meta ki Terms aur Advertising Policies ki pairwi ka wada karte hain, aur aap ke paas jis ad account ko jorte hain uska haq hona chahiye. Meta ke ads par kharch aur Meta ke faislon ki zimmedari hamari nahi.',
    'mkt.terms.g5Title': 'A5. Fees',
    'mkt.terms.g5Body': 'Fees plan ke mutabiq hain (order ke hisaab se). Tabdeeli ki soorat mein pehle itela di jayegi.',
    'mkt.terms.g6Title': 'A6. Aapka data aur privacy',
    'mkt.terms.g6Body': 'Aapka data aapka rehta hai. Hum usay Privacy Policy ke mutabiq sambhalte hain. Aap kabhi bhi apna data export ya delete karwa sakte hain.',
    'mkt.terms.g7Title': 'A7. Zimmedari ki had',
    'mkt.terms.g7Body': 'Service "jaisi hai" di jati hai. Qanoon ki ijazat ki had tak hum ghair-barah-e-raast ya munafa ke nuqsan ke zimmedar nahi. Courier-se mutaliq zimmedari Part B mein hai.',
    'mkt.terms.g8Title': 'A8. Khatma aur qanoon',
    'mkt.terms.g8Body': 'Aap kabhi bhi account band kar sakte hain. Hum shartein tornay par account band kar sakte hain. In Terms par Pakistan ka qanoon lagoo hoga. Sawal: {email}.',
    'mkt.dataDeletion.title': 'Data Deletion',
    'mkt.dataDeletion.intro': 'Yahan bataya gaya hai ke aap apna eNeezam aur Meta se mila hua data kaise delete karwa sakte hain.',
    'mkt.dataDeletion.m1Title': 'Tareeqa 1: Meta Connect mein Disconnect',
    'mkt.dataDeletion.m1Body': 'eNeezam mein login karein, Settings > Meta Connect kholein aur Disconnect dabayein. Aapka Meta access token, ad account, pixel aur Meta user ID hamare database se usi waqt hata diye jate hain.',
    'mkt.dataDeletion.m2Title': 'Tareeqa 2: Facebook se eNeezam hata dein',
    'mkt.dataDeletion.m2Body': 'Facebook > Settings > Business Integrations mein eNeezam ko remove karein. Meta hamein khud ba khud data deletion ki darkhwast bhejta hai aur hum us Facebook login se jura hua Meta data hata dete hain. Aapko ek confirmation code milta hai.',
    'mkt.dataDeletion.m3Title': 'Tareeqa 3: Email se darkhwast',
    'mkt.dataDeletion.m3Body': 'Apna account ya poora data delete karwane ke liye {email} par apne registered email se likhein aur store ka naam batayein. Hum aapki shanakht confirm karke account aur us se jura data hata dete hain.',
    'mkt.dataDeletion.statusTitle': 'Aapki darkhwast mil gayi',
    'mkt.dataDeletion.statusBody': 'Is confirmation code wali Meta data deletion darkhwast par amal ho chuka hai: us Facebook login se jura Meta data hamare active database se hata diya gaya hai.',
    'mkt.dataDeletion.codeLabel': 'Confirmation code',

