    'mkt.nav.solutions.meta': 'Meta Ads aur Pixel',
    'mkt.home.solution.meta.blurb': 'Apna Meta ad account jorein, ad performance eNeezam mein dekhein, aur chahein to apna Meta Pixel store par lagayein.',
    'mkt.sol.meta.title': 'Meta Ads aur Pixel',
    'mkt.sol.meta.subtitle': 'Apna Meta ad account eNeezam se jorein, ads ka hisaab apne orders ke sath dekhein, aur chahein to apna Meta Pixel apne eNeezam store par lagayein.',
    'mkt.sol.meta.f1.title': 'Apna ad account jorein',
    'mkt.sol.meta.f1.desc': 'Ek baar Facebook se login karein aur apna ad account chunein. Connection hamare server par chalta hai; access token aapke browser mein kabhi nahi dikhta.',
    'mkt.sol.meta.f2.title': 'Ad performance eNeezam mein',
    'mkt.sol.meta.f2.desc': 'Apne ad account ka kharch, impressions, clicks aur reach apne orders ke sath dekhein.',
    'mkt.sol.meta.f3.title': 'Meta Pixel store par (optional)',
    'mkt.sol.meta.f3.desc': 'Apna Pixel ID jorein to store PageView, ViewContent, AddToCart, InitiateCheckout aur Purchase events Meta ko bhejta hai. Aap apna Data sharing level chunte hain: Standard mein customer ka koi data nahi jata; Enhanced mein hashed email, phone, naam, shehar aur soobah; Maximum mein yehi data server se bhi (Conversions API) jata hai. Street address kabhi nahi bheja jata. Draft text hai, qanooni mashwara nahi.',
    'mkt.sol.meta.permTitle': 'Permissions aur aapka control',
    'mkt.sol.meta.permBody': 'eNeezam sirf do Meta permissions mangta hai: ads_read aur ads_management. eNeezam aapki taraf se kabhi post nahi karta. Aap kisi bhi waqt Meta Connect mein Disconnect kar sakte hain aur data delete karwane ki darkhwast de sakte hain.',
    'mkt.sol.meta.note': 'Meta Connect eNeezam ki Settings mein hai. Pixel sirf tab chalta hai jab aap apna Pixel ID save karein.',

    'mkt.footer.aboutBlurb': 'eNeezam Pakistani D2C brands ke liye ek hi jagah order management, courier booking, aur analytics deta hai — DewareKhas ki apni COD operations ki zaroorat se bana hua.',
