    'mkt.about.title': 'Hamari Kahani',
    'mkt.about.subtitle': 'DewareKhas ki apni zaroorat se, ek Pakistan-wide COD operations platform tak.',
    'mkt.about.storyP1': 'eNeezam ki kahani DewareKhas se shuru hoti hai — ek Pakistani D2C brand jo apne Shopify store se roz-marra COD orders process karta tha.',
    'mkt.about.storyP2': 'Jaise jaise order badhte gaye, Excel sheets aur WhatsApp groups se courier-booking aur order-tracking manage karna mushkil ho gaya. Hamari team ne apne liye internal tools banaye — order-approval workflow, courier-booking automation, aur profit-tracking — taake roz ka operational kaam manageable rahe.',
    'mkt.about.storyP3': 'Yeh internal tools itne kaam aaye ke humne inhe ek proper product bana kar dusre Pakistani D2C sellers ke liye bhi available kar diya — yehi eNeezam hai.',
    'mkt.about.missionTitle': 'Hamara Mission',
    'mkt.about.missionText': 'Har Pakistani D2C seller ko enterprise-level order aur courier management dena — bina enterprise-level complexity ya cost ke.',
    'mkt.about.visionTitle': 'Hamara Vision',
    'mkt.about.visionText': 'Pakistan ka sabse trusted all-in-one COD operations platform banna.',
    'mkt.about.teamTitle': 'Hamari Team',
    'mkt.about.teamSubtitle': 'Chhoti team, bara focus — apne sellers ke operations ko asaan banana.',
