    'mkt.contact.title': 'Rabta Karein',
    'mkt.contact.subtitle': 'Sawaal hai ya demo chahiye? Neeche form fill karo ya seedha email/call karo.',
    'mkt.contact.namePlaceholder': 'Aapka naam',
    'mkt.contact.emailPlaceholder': 'Aapka email',
