    'mkt.terms.title': 'Terms & Conditions',
    'mkt.terms.updatedPrefix': 'Aakhri update:',
    'mkt.terms.intro': 'Yeh Terms & Conditions eNeezam platform aur is se juri courier-booking services ke istemaal par lagoo hote hain. eNeezam sign-up karke ya use karke, aap in terms se ittefaq karte hain.',
    'mkt.terms.s1Title': '1. Service ka Daira (Scope)',
    'mkt.terms.s1Body': 'eNeezam ek order-management aur courier-booking platform hai jo Shopify stores ko courier partners (jaise Daraz Express) se jorta hai. eNeezam khud ek courier company nahi hai — asal pickup, transit, aur delivery hamesha courier partner ki responsibility hoti hai, eNeezam sirf booking/tracking ka digital layer provide karta hai.',
    'mkt.terms.s2Title': '2. Declared Value aur Liability Limits',
    'mkt.terms.s2Body': 'Har shipment ki declared value order ke invoice amount ke barabar mani jati hai, jab tak seller ne alag se kuch aur declare na kiya ho. Kisi bhi loss, damage, ya delay ki soorat mein eNeezam ki liability sirf us declared value tak mehdood hai — koi bhi indirect, consequential, ya lost-profit damages is mein shamil nahi. Asal claim-resolution aur compensation ka faisla courier partner ki apni policy ke mutabiq hota hai.',
    'mkt.terms.s3Title': '3. Delivery Timeframe Disclaimer',
    'mkt.terms.s3Body': 'eNeezam ya kisi courier partner ki taraf se batayi gayi estimated delivery timeframes sirf andaza hain, guarantee nahi. Weather, route-conditions, customer-availability, ya courier ke apne operational factors ki wajah se delivery mein deri ho sakti hai — is deri ke liye eNeezam zimmedar nahi hai.',
    'mkt.terms.s4Title': '4. Mana-Shuda (Prohibited) Items',
    'mkt.terms.s4Body': 'Ghair-qanooni items, hathyar/asla, aatishbazi ya koi bhi explosive/flammable material, nashay ki cheezein, zinda janwar, nakdi/currency, aur koi bhi item jo courier partner ki apni policy mein prohibited ho — inhe eNeezam ke through book nahi kiya ja sakta. Aisi kisi shipment ki zimmedari poori tarah seller/booking-karne-wale par hogi.',
    'mkt.terms.s5Title': '5. Payment Terms',
    'mkt.terms.s5Body': 'COD (Cash on Delivery) amount customer se courier partner collect karta hai aur apni policy ke mutabiq (deduction/fees ke baad) seller ko remit karta hai — is remittance ka schedule courier partner decide karta hai, eNeezam nahi. eNeezam ki apni subscription fees (plan ke mutabiq) alag se, order-count ke hisab se charge hoti hain.',
    'mkt.terms.s6Title': '6. Cancellations aur Returns',
    'mkt.terms.s6Body': 'Booking cancel karne ka option pickup se pehle tak available hai. Pickup ho jane ke baad cancellation courier partner ki apni policy ke tabe hai. Return/RTO (Return to Origin) shipments ki apni alag handling aur (agar applicable ho) additional charges ho sakte hain, jo courier partner tay karta hai.',
    'mkt.terms.s7Title': '7. Limitation of Liability',
    'mkt.terms.s7Body': 'eNeezam "as-is" (jaisa hai) basis par provide kiya jata hai. Hum kisi bhi service-interruption, third-party (Shopify/courier/payment-gateway) downtime, ya force-majeure events (jaise natural disasters, strikes, government restrictions) ki wajah se hone wale kisi bhi loss ke zimmedar nahi hain.',
    'mkt.terms.s8Title': '8. Terms Mein Tabdeeli',
    'mkt.terms.s8Body': 'Hum in terms ko kabhi bhi update kar sakte hain. Koi bhi material change hone par platform ke through ya email se inform kiya jayega. Terms update hone ke baad platform ka istemaal jari rakhna naye terms se ittefaq mana jayega.',
    'mkt.terms.s9Title': '9. Rabta (Contact)',
    'mkt.terms.s9Body': 'In terms ke bare mein kisi bhi sawaal ke liye support@eneezam.com par email karein ya 03152433123 par call karein.',

