    'mkt.footer.privacy': 'Privacy Policy',
    'mkt.footer.dataDeletion': 'Data Deletion',
    'mkt.privacy.title': 'Privacy Policy',
    'mkt.privacy.updatedPrefix': 'Last updated:',
    'mkt.privacy.intro': 'This Privacy Policy explains what data eNeezam collects and why, where it is kept, and what control you have. We never sell your data.',
    'mkt.privacy.s1Title': '1. Who we are',
    'mkt.privacy.s1Body': 'eNeezam is an order-management, courier-booking and online-store platform for sellers in Pakistan. For any question about this policy contact {email}.',
    'mkt.privacy.s2Title': '2. What we collect',
    'mkt.privacy.s2Body': 'Account data: name, email, phone, brand name. Store data: store name, domain, settings, products, theme. Order data: the orders of your customers, including customer name, phone and delivery address (we handle this on your behalf only to run orders and delivery). Technical data: basic logs for sign-in, errors and performance.',
    'mkt.privacy.s3Title': '3. Meta (Facebook) data',
    'mkt.privacy.s3Body': 'When you use Meta Connect we receive: your ad account ID and name, ad performance data (spend, impressions, clicks, reach), campaigns you create or pause through eNeezam, your Meta Pixel ID, your Meta user ID, and an access token. We ask for two permissions only: ads_read and ads_management. We use this data only to show you your ad results, to run campaigns when you ask us to, and for measurement through the pixel on your own store. We never use it for anyone else\'s advertising and never sell it. The merchant chooses the store\'s data sharing level: Standard sends no personal data to Meta; Enhanced sends the customer\'s hashed (SHA-256) email, phone, name, city, state and country; Maximum sends the same data also from our server (Conversions API) and passes the customer\'s IP address and user agent to Meta without storing or logging them. The street address is never sent.',
    'mkt.privacy.s4Title': '4. How we use data',
    'mkt.privacy.s4Body': 'To run the service (orders, courier booking, store, reports), to show it to you, to keep it secure and prevent fraud, and to fix problems. We do not give customer data to third parties for marketing.',
    'mkt.privacy.s5Title': '5. Where and how data is stored',
    'mkt.privacy.s5Body': 'Data is kept on Supabase (database) and Cloudflare (hosting and network). The Meta access token stays on our server in the database; it is never sent to your browser, URL, logs or device. Data is encrypted in transit and the database uses access control (row-level security) so every store sees only its own data.',
    'mkt.privacy.s6Title': '6. How long we keep it',
    'mkt.privacy.s6Body': 'Account and store data is kept while your account is active. Meta data (token, ad account, pixel) is kept until you Disconnect, delete your account, or remove eNeezam in Meta; then it is removed from our active database. Where law or accounting requires it, only the data that is required is kept.',
    'mkt.privacy.s7Title': '7. Our service providers',
    'mkt.privacy.s7Body': 'Supabase (database and sign-in) and Cloudflare (hosting, network, storefront). As needed: an email-sending service, courier partners (for your bookings), an AI service for matching delivery addresses, and Meta (when you connect it). They use data only to provide their service to us.',
    'mkt.privacy.s8Title': '8. Your rights',
    'mkt.privacy.s8Body': 'You may ask to see, correct or delete your data. You can remove your Meta data yourself at any time with Disconnect in Meta Connect. To delete your whole account or data, see the Data Deletion page or write to {email}.',
    'mkt.privacy.s9Title': '9. Changes and contact',
    'mkt.privacy.s9Body': 'We may update this policy and will tell you through the platform or by email if the change is significant. Questions: {email}.',
    'mkt.terms.generalTitle': 'Part A: General Terms of Service of the platform',
    'mkt.terms.courierTitle': 'Part B: Courier-booking service terms',
    'mkt.terms.generalIntro': 'By using eNeezam or creating an account you agree to these Terms. If you use it for a business, you confirm you have authority to bind that business.',
    'mkt.terms.g1Title': 'A1. The service',
    'mkt.terms.g1Body': 'eNeezam provides tools for orders, courier booking, products, an online store and ads. We may change or stop features and will try to give notice of major changes.',
    'mkt.terms.g2Title': 'A2. Your account and responsibilities',
    'mkt.terms.g2Body': 'You are responsible for your login, your team members and what they do. The data you provide must be accurate and lawful, and you must have the right to use your customers\' data.',
    'mkt.terms.g3Title': 'A3. Acceptable use',
    'mkt.terms.g3Body': 'The service may not be used to deceive, to sell unlawful goods, to take other people\'s data, or to damage the system.',
    'mkt.terms.g4Title': 'A4. Third-party services',
    'mkt.terms.g4Body': 'Services such as Shopify, courier companies and Meta have their own terms. When you use Meta Connect you agree to follow Meta\'s Terms and Advertising Policies and to have the right to the ad account you connect. We are not responsible for ad spend or for Meta\'s decisions.',
    'mkt.terms.g5Title': 'A5. Fees',
    'mkt.terms.g5Body': 'Fees follow your plan (per order). You will be told before they change.',
    'mkt.terms.g6Title': 'A6. Your data and privacy',
    'mkt.terms.g6Body': 'Your data stays yours. We handle it as described in the Privacy Policy. You can ask to export or delete it at any time.',
    'mkt.terms.g7Title': 'A7. Limits of liability',
    'mkt.terms.g7Body': 'The service is provided "as is". To the extent allowed by law we are not liable for indirect loss or lost profit. Courier-related liability is covered in Part B.',
    'mkt.terms.g8Title': 'A8. Ending and governing law',
    'mkt.terms.g8Body': 'You may close your account at any time. We may suspend an account that breaks these terms. These Terms are governed by the laws of Pakistan. Questions: {email}.',
    'mkt.dataDeletion.title': 'Data Deletion',
    'mkt.dataDeletion.intro': 'This page explains how to delete your eNeezam data and the data we received from Meta.',
    'mkt.dataDeletion.m1Title': 'Option 1: Disconnect in Meta Connect',
    'mkt.dataDeletion.m1Body': 'Sign in to eNeezam, open Settings > Meta Connect and press Disconnect. Your Meta access token, ad account, pixel and Meta user ID are removed from our database immediately.',
    'mkt.dataDeletion.m2Title': 'Option 2: Remove eNeezam in Facebook',
    'mkt.dataDeletion.m2Body': 'In Facebook > Settings > Business Integrations remove eNeezam. Meta then sends us a data deletion request automatically and we remove the Meta data tied to that Facebook login. You receive a confirmation code.',
    'mkt.dataDeletion.m3Title': 'Option 3: Request by email',
    'mkt.dataDeletion.m3Body': 'To delete your account or all your data, write to {email} from your registered email and tell us the store name. We confirm your identity and then remove the account and its data.',
    'mkt.dataDeletion.statusTitle': 'Your request was received',
    'mkt.dataDeletion.statusBody': 'The Meta data deletion request with this confirmation code has been processed: the Meta data tied to that Facebook login was removed from our active database.',
    'mkt.dataDeletion.codeLabel': 'Confirmation code',

