    'mkt.home.solution.meta.blurb': 'Connect your Meta ad account, see ad performance inside eNeezam, and optionally attach your Meta Pixel to your store.',
    'mkt.sol.meta.title': 'Meta Ads and Pixel',
    'mkt.sol.meta.subtitle': 'Connect your Meta ad account to eNeezam, see your ad results next to your orders, and optionally attach your Meta Pixel to your eNeezam store.',
    'mkt.sol.meta.f1.title': 'Connect your ad account',
    'mkt.sol.meta.f1.desc': 'Sign in with Facebook once and choose your ad account. The connection runs on our server; the access token is never shown in your browser.',
    'mkt.sol.meta.f2.title': 'Ad performance inside eNeezam',
    'mkt.sol.meta.f2.desc': 'See your ad account\'s spend, impressions, clicks and reach next to your orders.',
    'mkt.sol.meta.f3.title': 'Meta Pixel on your store (optional)',
    'mkt.sol.meta.f3.desc': 'Add your Pixel ID and your store sends PageView, ViewContent, AddToCart, InitiateCheckout and Purchase events to Meta. You choose the data sharing level: Standard sends no customer data; Enhanced adds hashed email, phone, name, city and state; Maximum also sends the same data from our server (Conversions API). The street address is never sent. Draft text, not legal advice.',
    'mkt.sol.meta.permTitle': 'Permissions and your control',
    'mkt.sol.meta.permBody': 'eNeezam asks for two Meta permissions only: ads_read and ads_management. eNeezam never posts for you. You can disconnect at any time in Meta Connect and request deletion of your data.',
    'mkt.sol.meta.note': 'Meta Connect is in eNeezam Settings. The pixel runs only after you save your Pixel ID.',

